// Package: Microsoft.EntityFrameworkCore.SqlServer
// Install: dotnet add package Microsoft.EntityFrameworkCore.SqlServer
//         dotnet add package Microsoft.EntityFrameworkCore.Tools

using Azure.Identity;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);

// Connection string loaded from Key Vault or App Configuration
var connectionString = builder.Configuration.GetConnectionString("Default");

// Configure EF Core with Azure SQL retry policy
builder.Services.AddDbContext<BlogContext>(options =>
    options.UseSqlServer(connectionString, sql =>
    {
        sql.EnableRetryOnFailure(
            maxRetryCount: 5,
            maxRetryDelay: TimeSpan.FromSeconds(10),
            errorNumbersToAdd: null);
        sql.CommandTimeout(30);
    }));

// Auto-apply pending migrations at startup (development only)
using (var scope = builder.Services.BuildServiceProvider().CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<BlogContext>();
    db.Database.Migrate();
}

var app = builder.Build();
app.MapGet("/posts", async (BlogContext db, CancellationToken ct) =>
    await db.Posts.ToListAsync(ct));
app.MapPost("/posts", async (Post post, BlogContext db, CancellationToken ct) =>
{
    db.Posts.Add(post);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/posts/{post.Id}", post);
});
app.Run();

public class BlogContext : DbContext
{
    public BlogContext(DbContextOptions<BlogContext> options)
        : base(options) { }

    public DbSet<Post> Posts => Set<Post>();
}

public class Post
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public DateTime PublishedAt { get; set; }
}

// Expected output on GET /posts:
// [ { "id": 1, "title": "Getting Started with Azure", "content": "...", "publishedAt": "2024-01-15" } ]

// Package: Microsoft.EntityFrameworkCore.SqlServer
// Install: dotnet add package Microsoft.EntityFrameworkCore.SqlServer

using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<BlogContext>();

    // Apply any pending migrations at startup
    // In production, prefer running 'dotnet ef database update' in your deployment pipeline
    try
    {
        db.Database.Migrate();
        Console.WriteLine("Migrations applied successfully");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Migration failed: {ex.Message}");
        throw;
    }
}

